<?php require __DIR__.'/../config/database.php';require __DIR__.'/../config/auth.php';require_role(['staff']);require __DIR__.'/../config/smart_ops.php';$msg=$err='';
$u=$pdo->prepare("SELECT * FROM users WHERE id=?");$u->execute([$_SESSION['user']['id']]);$me=$u->fetch();$pid=ensure_public_id($pdo,$me);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$product=(int)$_POST['product_id'];$qty=(float)$_POST['qty'];$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM shop_products WHERE id=? AND status='active' FOR UPDATE");$s->execute([$product]);$p=$s->fetch();if(!$p||$qty<=0||$p['stock_qty']<$qty)throw new Exception('Insufficient stock.');$sub=$p['price']*$qty;$disc=$p['staff_discount_eligible']?$sub*.10:0;$total=$sub-$disc;$pdo->prepare("INSERT INTO staff_shop_orders(staff_user_id,subtotal,discount_amount,total_amount,note) VALUES(?,?,?,?,?)")->execute([$_SESSION['user']['id'],$sub,$disc,$total,$p['name'].' × '.$qty.' '.$p['unit']]);$pdo->prepare("UPDATE shop_products SET stock_qty=stock_qty-? WHERE id=?")->execute([$qty,$product]);$pdo->commit();$msg='Staff purchase created with applicable 10% member discount.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}
$products=$pdo->query("SELECT * FROM shop_products WHERE status='active' AND stock_qty>0 ORDER BY category,name")->fetchAll();$orders=$pdo->prepare("SELECT * FROM staff_shop_orders WHERE staff_user_id=? ORDER BY id DESC LIMIT 10");$orders->execute([$_SESSION['user']['id']]);
$page_title='Staff Shop';require __DIR__.'/../partials/header.php';?>
<div class="container py-4"><div class="hero-top"><span class="badge-soft">STAFF ID: <?=htmlspecialchars($pid)?></span><h2 class="mt-2">🛒 Staff Member Shop</h2><p class="mb-0">Eligible products receive an automatic 10% staff-member discount.</p></div><?php if($msg):?><div class="alert alert-success mt-3"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert alert-danger mt-3"><?=$err?></div><?php endif;?><div class="row g-3 mt-2"><?php foreach($products as $p):?><div class="col-md-4"><div class="cardx p-3 h-100"><?php if($p['image_path']):?><img class="real-product-img" src="<?=url_path($p['image_path'])?>"><?php else:?><div class="product-placeholder"><?=$p['icon']?:'🌿'?></div><?php endif;?><h4><?=htmlspecialchars($p['name'])?></h4><div class="price">৳<?=number_format($p['price'],2)?> / <?=$p['unit']?></div><?php if($p['staff_discount_eligible']):?><span class="staff-discount">10% STAFF OFF</span><?php endif;?><form method="post" class="d-flex gap-2 mt-3"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input class="form-control" type="number" step=".01" min=".01" max="<?=$p['stock_qty']?>" name="qty" value="1"><button class="btn btn-success">Buy</button></form></div></div><?php endforeach;?></div></div>
